                    </div>
                    <PremiumButton onClick={() => { setCurrentBlog({ category: 'Web Development', status: 'Draft' }); setIsEditing(true); }} icon={true} className="!px-6 !py-2 text-xs">Manual Post</PremiumButton>
                </div>
            </div>

            {/* Editing UI */}
            <AnimatePresence>
                {isEditing && (
