                                    { n: 1, t: "Identity", s: "Basic Info" },
                                    { n: 2, t: "Capability", s: "Services Required" },
                                    { n: 3, t: "Logistics", s: "Budget & Time" },
                                    { n: 4, t: "The Vision", s: "Briefing" }
