                {/* Gradients Overlay */}
                <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-slate-950/20 to-transparent opacity-90 group-hover:opacity-60 transition-opacity"></div>

                {/* Bio Reveal Overlay */}
                <div className="absolute inset-0 bg-cyan-950/95 backdrop-blur-xl p-8 flex flex-col justify-center translate-y-full group-hover:translate-y-0 transition-transform duration-500 ease-out z-20">
